# ---- Chèn an toàn + dedup ----
d = json.load(open(F, encoding="utf-8")) if os.path.exists(F) else []
# 1) Dedup JSON hiện có (giữ bản ghi xuất hiện đầu tiên)
seen, uniq = set(), []
for p in d:
    s = p.get("slug")
    if s in seen:
        continue
    seen.add(s)
    uniq.append(p)
removed_dups = len(d) - len(uniq)
d = uniq
# 2) Thêm slug mới, tránh trùng nội bộ NEW và trùng JSON
added = []
for p in NEW:
    if p["slug"] in seen:
        continue
    seen.add(p["slug"])
    added.append(p)
d += added
json.dump(d, open(F, "w", encoding="utf-8"), ensure_ascii=False, indent=2)
print("Đã thêm:", len(added), "| Gỡ trùng cũ:", removed_dups, "| Tổng Thái Nguyên:", len(d))
print("Slug mới:", ", ".join(p["slug"] for p in added))
